import{_ as t,o as n,c as s,a5 as e}from"./chunks/framework.Bhkz_BpM.js";const b=JSON.parse('{"title":"MS-03 Matlab Function 使用","description":"","frontmatter":{"title":"MS-03 Matlab Function 使用","date":"2026-07-09T00:00:00.000Z","quality":"curated","status":"learning","visibility":"public","order":40,"summary":"讲清 Matlab Function 模块适合封装什么、输入输出如何定型、persistent 状态如何保存，以及代码生成前要检查什么。"},"headers":[],"relativePath":"content/matlab-simulink/custom-blocks/MS-03-Matlab-Function.md","filePath":"content/matlab-simulink/custom-blocks/MS-03-Matlab-Function.md","lastUpdated":null}'),l={name:"content/matlab-simulink/custom-blocks/MS-03-Matlab-Function.md"};function i(p,a,d,o,c,r){return n(),s("div",null,[...a[0]||(a[0]=[e(`<h1 id="ms-03-matlab-function-使用" tabindex="-1">MS-03 Matlab Function 使用 <a class="header-anchor" href="#ms-03-matlab-function-使用" aria-label="Permalink to &quot;MS-03 Matlab Function 使用&quot;">​</a></h1><p>Matlab Function 模块适合把一小段算法放进 Simulink，例如限幅、坐标变换、离散控制器、状态机。它不适合一开始就塞进整个系统。</p><h2 id="_1-适合封装的内容" tabindex="-1">1. 适合封装的内容 <a class="header-anchor" href="#_1-适合封装的内容" aria-label="Permalink to &quot;1. 适合封装的内容&quot;">​</a></h2><div class="kb-table-scroll"><table><thead><tr><th>内容</th><th>是否适合</th><th>原因</th></tr></thead><tbody><tr><td>简单数学变换</td><td>适合</td><td>输入输出清楚</td></tr><tr><td>离散 PI 控制器</td><td>适合</td><td>可以用 <code>persistent</code> 保存积分状态</td></tr><tr><td>复杂对象模型</td><td>谨慎</td><td>调试不如框图直观</td></tr><tr><td>大量文件读写</td><td>不适合</td><td>仿真和代码生成边界不清</td></tr><tr><td>参数扫描外层流程</td><td>不适合</td><td>应放在 Matlab 脚本控制</td></tr></tbody></table></div><h2 id="_2-最小-pi-模块" tabindex="-1">2. 最小 PI 模块 <a class="header-anchor" href="#_2-最小-pi-模块" aria-label="Permalink to &quot;2. 最小 PI 模块&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>function u = pi_controller(ref, fbk, Kp, Ki, Ts, uMax)</span></span>
<span class="line"><span>%#codegen</span></span>
<span class="line"><span>persistent integ</span></span>
<span class="line"><span>if isempty(integ)</span></span>
<span class="line"><span>    integ = 0;</span></span>
<span class="line"><span>end</span></span>
<span class="line"><span></span></span>
<span class="line"><span>err = ref - fbk;</span></span>
<span class="line"><span>integ = integ + Ts * err;</span></span>
<span class="line"><span>integ = min(max(integ, -uMax), uMax);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>u = Kp * err + Ki * integ;</span></span>
<span class="line"><span>u = min(max(u, -uMax), uMax);</span></span>
<span class="line"><span>end</span></span></code></pre></div><p><code>persistent</code> 相当于模块内部状态。它在仿真开始时初始化，在每个采样周期保留上一次值。新手要特别注意：如果你点击停止再运行，状态会重新初始化；如果只暂停再继续，状态不会丢。</p><h2 id="_3-输入输出定型" tabindex="-1">3. 输入输出定型 <a class="header-anchor" href="#_3-输入输出定型" aria-label="Permalink to &quot;3. 输入输出定型&quot;">​</a></h2><p>Matlab Function 最容易报错的地方是尺寸和类型不明确。推荐在模块编辑器里明确：</p><div class="kb-table-scroll"><table><thead><tr><th>项目</th><th>建议</th></tr></thead><tbody><tr><td>输入维度</td><td>标量写 <code>1</code>，向量写固定长度</td></tr><tr><td>数据类型</td><td>控制算法先用 <code>double</code> 验证，再考虑 <code>single</code> 或定点</td></tr><tr><td>可变尺寸</td><td>新手阶段先关闭</td></tr><tr><td>采样时间</td><td>由外部离散模块或触发子系统控制</td></tr></tbody></table></div><h2 id="_4-代码生成前检查" tabindex="-1">4. 代码生成前检查 <a class="header-anchor" href="#_4-代码生成前检查" aria-label="Permalink to &quot;4. 代码生成前检查&quot;">​</a></h2><p>如果这个模块未来要生成 C 代码，先避免这些写法：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>% 不建议在可生成代码模块里使用</span></span>
<span class="line"><span>eval(&#39;Kp = 1&#39;);</span></span>
<span class="line"><span>load(&#39;params.mat&#39;);</span></span>
<span class="line"><span>plot(y);</span></span>
<span class="line"><span>disp(&quot;debug text&quot;);</span></span></code></pre></div><p>更稳的做法是把参数作为输入或 Simulink.Parameter 管理，把调试输出交给 Scope、To Workspace 或日志模块。</p><h2 id="_5-新手调试顺序" tabindex="-1">5. 新手调试顺序 <a class="header-anchor" href="#_5-新手调试顺序" aria-label="Permalink to &quot;5. 新手调试顺序&quot;">​</a></h2><p>先用常数输入测试模块，再接入真实反馈。先验证无状态算法，再加入 <code>persistent</code> 状态。先在浮点下跑通，再考虑定点和代码生成。每次只增加一个复杂度，问题会少很多。</p>`,16)])])}const h=t(l,[["render",i]]);export{b as __pageData,h as default};
